        JsonNode retry = postOk("/api/channels/" + channel + "/readings",
                readingsBody(commandKey, channel, new String[][]{
                        {"2026-11-10T10:30:00Z", "4"},
                        {"2026-11-10T11:00:00Z", "5"}}), "alice");
